<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import { longMonitorApi } from '@/api/longMonitor'
const rows=ref<any[]>([]),total=ref(0),loading=ref(false),q=reactive<any>({page:1,size:20,status:''}),data=(r:any)=>r.data.data
async function load(){loading.value=true;try{const d=data(await longMonitorApi.notifications(q));rows.value=d.items||[];total.value=d.total||0}finally{loading.value=false}}onMounted(load)
</script><template><div class="page"><div><h2>通知记录</h2><p>记录长效代理异常或恢复通过客户钉钉/飞书机器人发送的结果。</p></div><el-card shadow="never"><div class="filters"><el-select v-model="q.status" placeholder="发送状态" clearable><el-option v-for="x in ['SUCCESS','FAILED']" :key="x" :label="x" :value="x"/></el-select><el-button type="primary" @click="load">查询</el-button></div><el-table :data="rows" v-loading="loading" stripe><el-table-column prop="created_at" label="创建时间" width="180"/><el-table-column prop="customer_name" label="客户"/><el-table-column prop="monitor_no" label="监控编号"/><el-table-column prop="bot_name" label="机器人"/><el-table-column prop="channel" label="渠道"/><el-table-column prop="notification_type" label="类型"/><el-table-column prop="send_status" label="发送状态"/><el-table-column prop="error_message" label="错误信息" min-width="180"/></el-table><div class="pager"><el-pagination v-model:current-page="q.page" v-model:page-size="q.size" :total="total" layout="total,sizes,prev,pager,next" @change="load"/></div></el-card></div></template><style scoped>.page{display:grid;gap:16px}h2{margin:0 0 6px}p{margin:0;color:#7b8494}.filters{display:flex;gap:10px;margin-bottom:14px}.pager{display:flex;justify-content:flex-end;margin-top:14px}</style>